-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/snapshots/snap_patient_demographics.yml. Do not edit.
-- First load only: every record becomes its first version. Later changes are tracked by dbt snapshot
-- (dbt snapshot --target snowflake), which closes a version and adds a new one when one of these changes:
-- address_line, city, state, postal_code, sex, is_deceased.
CREATE TABLE IF NOT EXISTS snap_patient_demographics AS
SELECT
    d.*,
    MD5(CAST(d.patient_id AS VARCHAR) || '|' || CAST(d.loaded_at AS VARCHAR)) AS dbt_scd_id,
    d.loaded_at AS dbt_updated_at,
    d.loaded_at AS dbt_valid_from,
    CAST(NULL AS TIMESTAMP_NTZ) AS dbt_valid_to
FROM int_patient_demographics d;
